// ── CITRUS real-data layer (same API as before; no synthetic data) ──────────
// Waveforms / candidates come from reference/01_real_windows (subject 00020,
// three isolated 30 s windows). Candidate scores, decoded HR and reliability
// are the supplied current-HGB model's actual outputs on those windows,
// generated by scripts/build_real_data.py with the authors' weights
// (self-checked against the verified 05 replay: decoded exact, rel. <1e-5).
// Published numbers live ONLY in PUBLISHED (paper / workshop source tables).
import raw from './real-data.json'

export type Method = 'Welch PSD' | 'Autocorrelation' | 'Peak-interval'
export interface Candidate {
  id: string; hr: number; method: Method; channel: 'IR' | 'Red'
  power: number; harmonic: '0.5×' | '1×' | '2×' | '—'; isMotionPeak: boolean
  score: number; cost: number
  feats: { spectral: number; consensus: number; harmonic: number; source: number; temporal: number }
}
export interface Win {
  idx: number; t0: number; trueHR: number; motionFreqBPM: number; motionAmp: number
  candidates: Candidate[]; independentHR: number; viterbiHR: number
  reliability: number; errIndep: number; errVit: number
}
export interface Recording {
  id: string; label: string; sub: string; motion: string; nWindows: number
  trueBase: number; windows: Win[]
  series: { t: number; ir: number; red: number; acc: number; refHR: number }[]
  psd: { bpm: number; ir: number; red: number }[]
  autocorr: { lagBPM: number; v: number }[]
}

interface Win01 {
  id: string; label: string; subject: string; fsHz: number; refHR: number; accStd: number; accPeakBpm: number
  baseHR: number; decodedHR: number; reliability: number
  wave: { t: number[]; ir: number[]; red: number[]; ax: number[]; ay: number[]; az: number[] }
  psd: { bpm: number[]; ir: number[]; red: number[] }
  autocorrBpm: number[]; autocorr: number[]
  candidates: {
    idx: number; bpm: number; quality: number; channel: 'IR' | 'Red'; method: string; harmonic: string
    density5: number; density10: number; weightedDensity10: number; irQuality: number; redQuality: number
    prob: number; scoreNorm: number; emissionCost: number
  }[]
}
const W01 = (raw as unknown as { windows01: Win01[] }).windows01

const METHOD_MAP: Record<string, Method> = {
  'Welch spectral': 'Welch PSD', 'Autocorrelation': 'Autocorrelation',
  'Peak interval (+)': 'Peak-interval', 'Peak interval (-)': 'Peak-interval',
}
const REC_META: Record<string, { id: string; label: string; sub: string; motion: string }> = {
  rest: { id: 'rest', label: 'Rest', sub: 'Subject 00020 · original label “sitting”', motion: 'Static' },
  squat: { id: 'squats', label: 'Deep squats', sub: 'Subject 00020 · original label “deepsquat”', motion: 'Deep-squat protocol' },
  stride: { id: 'striding', label: 'Striding', sub: 'Subject 00020 · original label “striding”', motion: 'Striding protocol' },
}

function buildRecording(w: Win01): Recording {
  const meta = REC_META[w.id]
  const motionFreqBPM = w.accStd >= 20 ? w.accPeakBpm : 0 // ACC spectral peak only where stored ACC actually moves
  const series = w.wave.t.map((t, i) => ({
    t, ir: w.wave.ir[i], red: w.wave.red[i],
    acc: Math.hypot(w.wave.ax[i], w.wave.ay[i], w.wave.az[i]), refHR: w.refHR,
  }))
  const candidates: Candidate[] = w.candidates.map(c => ({
    id: `${w.id}-${c.idx}`, hr: c.bpm, method: METHOD_MAP[c.method] ?? 'Welch PSD', channel: c.channel,
    power: c.quality, harmonic: (c.harmonic === '—' ? '—' : c.harmonic) as Candidate['harmonic'],
    isMotionPeak: motionFreqBPM > 0 && Math.abs(c.bpm - motionFreqBPM) <= 3,
    score: c.scoreNorm, cost: c.emissionCost,
    feats: {
      spectral: c.quality, consensus: c.density5, harmonic: c.density10,
      source: c.weightedDensity10, temporal: c.channel === 'IR' ? c.irQuality : c.redQuality,
    },
  }))
  const win: Win = {
    idx: 0, t0: 0, trueHR: w.refHR, motionFreqBPM, motionAmp: w.accStd, candidates,
    independentHR: w.baseHR, viterbiHR: w.decodedHR, reliability: w.reliability,
    errIndep: Math.abs(w.baseHR - w.refHR), errVit: Math.abs(w.decodedHR - w.refHR),
  }
  return {
    id: meta.id, label: meta.label, sub: meta.sub, motion: meta.motion, nWindows: 1, trueBase: w.refHR,
    windows: [win], series,
    psd: w.psd.bpm.map((bpm, i) => ({ bpm, ir: w.psd.ir[i], red: w.psd.red[i] })),
    autocorr: w.autocorrBpm.map((lagBPM, i) => ({ lagBPM, v: w.autocorr[i] })),
  }
}
export const RECORDINGS: Recording[] = W01.map(buildRecording)

// ── Verified sequential replay (05_verified_HGB_replay) ─────────────────────
// Five *consecutive* held-out windows (subject 00001, source indices 67–71:
// two static "spo2" windows then three "deepsquat" windows), scored by the
// authors' HGB model with the real causal DP already run. This is the only
// sequential sequence in the data package, so Stage 4 (step decoder) and
// Stage 5 (reliability timeline) run on it — the isolated subject-00020
// windows above each contain a single window and cannot be stepped through.
interface ReplayCand01 {
  idx: number; bpm: number; predErr: number; prob: number; emissionCost: number
  dpCost: number; transCost: number; predIdx: number; predBpm: number | null
  independent: boolean; causal: boolean; quality: number
  channel: 'IR' | 'Red'; method: string; harmonic: string
}
interface ReplayWin01 {
  idx: number; sourceIndex: number; label: string; isMotion: boolean; subject: string
  refHR: number; candidateCount: number; baseHR: number; decodedHR: number
  selectedIdx: number; decoderConfidence: number; reliability: number
  threshold: number; report: boolean
  relFeats: { cand_std: number; consensus_5bpm: number; consensus_10bpm: number; quality_mean: number; near_pred_std: number; valid_count: number }
  candidates: ReplayCand01[]
}
export interface ReplayCandidate {
  id: string; hr: number; method: Method; channel: 'IR' | 'Red'
  harmonic: '0.5×' | '1×' | '2×' | '—'; isMotionPeak: boolean
  power: number; prob: number; predErr: number
  emissionCost: number; dpCost: number; transCost: number; predBpm: number | null
  independent: boolean; causal: boolean
}
export interface ReplayWin {
  idx: number; sourceIndex: number; label: string; isMotion: boolean; subject: string
  trueHR: number; independentHR: number; viterbiHR: number
  reliability: number; report: boolean; threshold: number; decoderConfidence: number
  errIndep: number; errVit: number
  relFeats: ReplayWin01['relFeats']; candidates: ReplayCandidate[]
}
const REPLAY_RAW = (raw as unknown as { replay: { windows: ReplayWin01[]; lambdaTransition: number; threshold: number; heldOutSubject: string; candidateTrees: number; reliabilityTrees: number; verification: { candidate_rows: number; windows: number } } }).replay
export const REPLAY: { windows: ReplayWin[]; lambdaTransition: number; threshold: number; heldOutSubject: string; candidateRows: number } = {
  lambdaTransition: REPLAY_RAW.lambdaTransition,
  threshold: REPLAY_RAW.threshold,
  heldOutSubject: REPLAY_RAW.heldOutSubject,
  candidateRows: REPLAY_RAW.verification.candidate_rows,
  windows: REPLAY_RAW.windows.map(w => ({
    idx: w.idx, sourceIndex: w.sourceIndex, label: w.label, isMotion: w.isMotion, subject: w.subject,
    trueHR: w.refHR, independentHR: w.baseHR, viterbiHR: w.decodedHR,
    reliability: w.reliability, report: w.report, threshold: w.threshold,
    decoderConfidence: w.decoderConfidence,
    errIndep: Math.abs(w.baseHR - w.refHR), errVit: Math.abs(w.decodedHR - w.refHR),
    relFeats: w.relFeats,
    candidates: w.candidates.map(c => ({
      id: `replay-${w.idx}-${c.idx}`, hr: c.bpm, method: METHOD_MAP[c.method] ?? 'Welch PSD', channel: c.channel,
      harmonic: (c.harmonic === '—' ? '—' : c.harmonic) as ReplayCandidate['harmonic'],
      isMotionPeak: w.isMotion, power: c.quality, prob: c.prob, predErr: c.predErr,
      emissionCost: c.emissionCost, dpCost: c.dpCost, transCost: c.transCost, predBpm: c.predBpm,
      independent: c.independent, causal: c.causal,
    })),
  })),
}

export type PolicyKey = 'l30' | 'l8' | 'l4'
export const POLICIES: Record<PolicyKey, { label: string; suffix: string; lambda: number; coverage: string; motionMAE: string; note: string; thresh: number }> = {
  l30: { label: 'λrej = 30 · full coverage', suffix: 'full coverage', lambda: 30, coverage: '100%', motionMAE: '9.99 BPM', note: 'Policy emits every window — accepts or holds through unreliable stretches.', thresh: 0.18 },
  l8: { label: 'λrej = 8 · balanced', suffix: 'balanced', lambda: 8, coverage: '~50–70%', motionMAE: '6.2 BPM @ 50%', note: 'Rejects the least reliable windows; holds briefly before rejecting.', thresh: 0.45 },
  l4: { label: 'λrej = 4 · spot-check', suffix: 'spot-check', lambda: 4, coverage: '31%', motionMAE: '2.90 BPM', note: 'High-confidence spot measurements only — comparable to static-window accuracy.', thresh: 0.68 },
}
export type Decision = 'accept' | 'hold' | 'reject'
export function decide(w: Win, thresh: number, prevDecision: Decision | null, heldHR: number | null): { d: Decision; reported: number | null } {
  if (w.reliability >= thresh) return { d: 'accept', reported: w.viterbiHR }
  if (w.reliability >= thresh * 0.55 && heldHR !== null && prevDecision !== 'reject') return { d: 'hold', reported: heldHR }
  return { d: 'reject', reported: null }
}

